  /// Always throws on the web.
  Future<int> start({Duration timeout = const Duration(minutes: 5)}) =>
      throw UnsupportedError('Local servers are not supported on the web.');

  /// Always throws on the web.
  Future<String?> waitForToken() =>
      throw UnsupportedError('Local servers are not supported on the web.');

  /// No-op on the web.
  Future<void> close() async {}
}

